# aplicar-v67-impulsionamento-admin-superadmin.ps1
# Cria fluxo de impulsionamento pago:
#
# ADMIN:
# - /admin/boosts
# - escolhe local de impulsionamento
# - informa pagamento
# - envia para aprovacao
#
# SUPER_ADMIN:
# - /admin/support
# - ve valores pagos
# - aprova ou reprova
#
# Planos:
# - Carrossel principal: R$ 250 a cada 15 dias ate a data do evento
# - Banner publicidade: R$ 100 a cada mes ate a data do evento
# - Espacos das secoes: R$ 100 a cada mes ate a data do evento

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v67-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Add-BoostModelToPrisma() {
  $SchemaPath = Join-Path $Root "apps\api\prisma\schema.prisma"

  if (-not (Test-Path $SchemaPath)) {
    throw "schema.prisma nao encontrado."
  }

  $Schema = Get-Content $SchemaPath -Raw

  if ($Schema -match "model\s+PromotionBoostRequest\s+\{") {
    Write-Host "Modelo PromotionBoostRequest ja existe no Prisma." -ForegroundColor Yellow
    return
  }

  $Backup = "$SchemaPath.bak-v67-$Stamp"
  Copy-Item $SchemaPath $Backup -Force
  Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

  $Model = @'

model PromotionBoostRequest {
  id       String @id @default(uuid())
  protocol String @unique

  requesterUserId String
  requesterRole   String?
  requesterName   String?
  requesterEmail  String?
  requesterCpf    String?

  eventId    String?
  eventTitle String
  eventDate  DateTime

  placement            String
  placementLabel       String
  placementDescription String?
  periodDays           Int
  unitPriceCents       Int
  cycles               Int
  totalAmountCents     Int

  startsAt DateTime
  endsAt   DateTime

  paymentStatus    String  @default("DECLARED_PAID")
  paymentMethod    String?
  paymentReference String?
  paymentProofText String?
  notes            String?

  status      String   @default("PAID_PENDING_REVIEW")
  submittedAt DateTime @default(now())

  moderatorUserId String?
  moderatorName   String?
  moderatorEmail  String?
  moderatorNote   String?
  reviewedAt      DateTime?
  approvedAt      DateTime?
  rejectedAt      DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([requesterUserId])
  @@index([requesterEmail])
  @@index([status])
  @@index([placement])
  @@index([startsAt])
  @@index([endsAt])
}

'@

  Add-Content -Path $SchemaPath -Value $Model -Encoding UTF8
  Write-Host "Modelo PromotionBoostRequest adicionado ao schema.prisma." -ForegroundColor Green
}

function Patch-AppModule() {
  $AppModulePath = Join-Path $Root "apps\api\src\app.module.ts"

  if (-not (Test-Path $AppModulePath)) {
    throw "app.module.ts nao encontrado."
  }

  $Content = Get-Content $AppModulePath -Raw

  if ($Content -match "PromotionBoostsModule") {
    Write-Host "PromotionBoostsModule ja existe no app.module.ts." -ForegroundColor Yellow
    return
  }

  $Backup = "$AppModulePath.bak-v67-$Stamp"
  Copy-Item $AppModulePath $Backup -Force
  Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray

  $ImportLine = "import { PromotionBoostsModule } from './promotion-boosts/promotion-boosts.module';"
  $LastImportMatch = [regex]::Matches($Content, "import\s+.*?;\s*") | Select-Object -Last 1

  if ($null -eq $LastImportMatch) {
    $Content = $ImportLine + "`r`n" + $Content
  } else {
    $InsertAt = $LastImportMatch.Index + $LastImportMatch.Length
    $Content = $Content.Insert($InsertAt, "`r`n$ImportLine")
  }

  if ($Content -match "imports\s*:\s*\[") {
    $Content = [regex]::Replace(
      $Content,
      "imports\s*:\s*\[",
      "imports: [`r`n    PromotionBoostsModule,",
      1
    )
  } else {
    throw "Nao encontrei imports: [ no app.module.ts"
  }

  Set-Content -Path $AppModulePath -Value $Content -Encoding UTF8
  Write-Host "PromotionBoostsModule adicionado ao app.module.ts." -ForegroundColor Green
}

function Patch-HeaderLinks() {
  $HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

  if (-not (Test-Path $HeaderPath)) {
    Write-Host "Aviso: CustomerHeader.tsx nao encontrado." -ForegroundColor Yellow
    return
  }

  $Content = Get-Content $HeaderPath -Raw
  $Original = $Content

  # troca link antigo de solicitacoes de criador por impulsionamentos
  $Content = $Content.Replace('Solicitações de criador", href: "/admin/support?tab=admin-requests"', 'Impulsionamentos", href: "/admin/support"')
  $Content = $Content.Replace('Solicitacoes de criador", href: "/admin/support?tab=admin-requests"', 'Impulsionamentos", href: "/admin/support"')
  $Content = $Content.Replace('Solicitações de criador", href: "/admin/support/admin-requests"', 'Impulsionamentos", href: "/admin/support"')
  $Content = $Content.Replace('Solicitacoes de criador", href: "/admin/support/admin-requests"', 'Impulsionamentos", href: "/admin/support"')

  # adiciona Impulsionar evento depois de Criar evento nos menus admin se ainda nao tiver
  if ($Content -notmatch 'Impulsionar evento') {
    $Content = $Content.Replace(
      '{ label: "Criar evento", href: "/admin/events/new" },',
      '{ label: "Criar evento", href: "/admin/events/new" },' + "`r`n" + '    { label: "Impulsionar evento", href: "/admin/boosts" },'
    )
  }

  if ($Content -ne $Original) {
    $Backup = "$HeaderPath.bak-v67-$Stamp"
    Copy-Item $HeaderPath $Backup -Force
    Set-Content -Path $HeaderPath -Value $Content -Encoding UTF8
    Write-Host "Header atualizado com Impulsionamentos." -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
}

function Stop-NodeForPrisma() {
  Write-Host "Parando processos node.exe para evitar EPERM no Prisma..." -ForegroundColor Yellow
  Get-Process node -ErrorAction SilentlyContinue | ForEach-Object {
    try {
      Stop-Process -Id $_.Id -Force -ErrorAction Stop
    } catch {
      Write-Host "Nao consegui parar node PID $($_.Id)." -ForegroundColor Yellow
    }
  }
  Start-Sleep -Seconds 2
}

function Run-Prisma() {
  $ApiPath = Join-Path $Root "apps\api"

  if (-not (Test-Path $ApiPath)) {
    throw "Pasta apps\api nao encontrada."
  }

  Stop-NodeForPrisma

  Push-Location $ApiPath

  try {
    Write-Host "Rodando: npx prisma db push" -ForegroundColor Cyan
    npx prisma db push

    if ($LASTEXITCODE -ne 0) {
      throw "npx prisma db push falhou."
    }

    Write-Host "Rodando: npx prisma generate" -ForegroundColor Cyan
    npx prisma generate

    if ($LASTEXITCODE -ne 0) {
      throw "npx prisma generate falhou."
    }
  }
  finally {
    Pop-Location
  }
}

Write-Host "Aplicando v67 - impulsionamento pago..." -ForegroundColor Cyan

Write-TextBase64File "apps\api\src\promotion-boosts\dto\create-promotion-boost-request.dto.ts" ""
Write-TextBase64File "apps\api\src\promotion-boosts\dto\review-promotion-boost-request.dto.ts" ""
Write-TextBase64File "apps\api\src\promotion-boosts\promotion-boosts.module.ts" ""
Write-TextBase64File "apps\api\src\promotion-boosts\promotion-boosts.controller.ts" ""
Write-TextBase64File "apps\api\src\promotion-boosts\promotion-boosts.service.ts" ""
Write-TextBase64File "apps\web\src\app\admin\boosts\page.tsx" ""
Write-TextBase64File "apps\web\src\app\admin\support\page.tsx" ""

Add-BoostModelToPrisma
Patch-AppModule
Patch-HeaderLinks
Run-Prisma

Write-Host ""
Write-Host "v67 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Rotas:" -ForegroundColor Cyan
Write-Host "- Admin solicita impulsionamento: /admin/boosts" -ForegroundColor Cyan
Write-Host "- Super admin aprova/reprova: /admin/support" -ForegroundColor Cyan
Write-Host "- Endpoint publico dos aprovados: /v1/promotion-boosts/public" -ForegroundColor Cyan
Write-Host ""
Write-Host "Agora reinicie API e WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\api"' -ForegroundColor Cyan
Write-Host "npm run start:dev" -ForegroundColor Cyan
Write-Host ""
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
